const items = $input.all();
const fails = [];
for (const item of items) {
  const j = item.json || {};
  if (j.error) {
    const desc = (item.error && item.error.description) || j.error;
    fails.push(String(desc));
  }
}
if (fails.length) {
  throw new Error('Facebook page post failed: ' + fails.join(' | '));
}
return [{ json: { facebookOk: true, pages: items.length } }];

const kind = "post";
const j = $input.first().json || {};
const videoId = String(j.videoId || '');
const requestId = String(j.requestId || '');
const staticData = $getWorkflowStaticData('global');
staticData[kind] = staticData[kind] || {};
let skipped = '';
if (videoId && !requestId && staticData[kind][videoId]) skipped = 'duplicate';
return [{ json: { ...j, skipped } }];

const raw = $input.first().json || {};
const code = String(raw.status_code || '').toUpperCase();
if (code === 'ERROR' || raw.error) {
  throw new Error('Instagram media ERROR: ' + JSON.stringify(raw).slice(0, 400));
}
return [{ json: { ...raw, igReady: code === 'FINISHED' } }];

