function ran(name) { try { return $(name).all(); } catch (e) { return null; } }
function failed(items) {
  if (!items) return true;
  for (const item of items) {
    const j = item.json || {};
    if (j.error || (item.error && item.error.message)) return true;
  }
  return false;
}
const pack = $("Pack beats").first().json;
const p = pack.platforms;
const all = p == null || p === '' || (Array.isArray(p) && p.length === 0);
const want = (n) => all || (Array.isArray(p) && p.map(String).includes(n));
const fails = [];
if (want('instagram')) {
  const items = ran('Instagram publish');
  if (!items || failed(items)) fails.push('instagram');
}
if (want('tiktok')) {
  const items = ran('Buffer TikTok');
  if (!items || failed(items)) fails.push('tiktok');
}
if (fails.length) throw new Error('Social post failed: ' + fails.join(', '));
return [{ json: { socialOk: true, videoId: pack.videoId } }];

